/*
 * A154810  Nonpalindromic numbers with binary digits only.
 * https://oeis.org/A154810
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 21, u32 n <= 961, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_palindrome
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes A154810: the nth positive integer whose decimal
 * representation consists solely of digits 0 and 1 and is NOT a
 * palindrome.  The sequence is generated by enumerating every
 * integer made of binary digits (written as decimal numbers) and
 * skipping the palindromic ones. */

/* If the build supplies utilities, the following header declares
 * the helper function is_palindrome(seq_t,x,10).  Adjust the path if
 * necessary. */
#include <stdbool.h>
#include "../utils/is_palindrome.h"

seq_t a(idx_t n)
{
    /* Undefined for n = 0; the problem definition starts at n = 1. */
    if (n == 0) return 0;

    idx_t found = 0;                /* number of valid terms found */

    /* Iterate over lengths of the decimal strings (number of digits). */
    for (int len = 1; ; ++len)
    {
        /* The first binary number of this length has a leading 1
         * (e.g. len=3 -> 100b = 4 decimal).  The last one has all bits 1. */
        idx_t start = ((idx_t)1) << (len - 1);
        idx_t end   = ((idx_t)1 << len) - 1;

        for (idx_t m = start; m <= end; ++m)
        {
            /* Convert the binary number m into a decimal number whose
             * digits are the bits of m.  Example: m = 5 (binary 101)
             * becomes decimal 101. */
            seq_t v   = 0;
            seq_t mult = 1;
            idx_t tmp = m;
            while (tmp > 0)
            {
                if (tmp & 1ULL) v += mult;
                mult *= 10;
                tmp >>= 1;
            }

            /* Skip palindromic values. */
            if (is_palindrome(v, 10)) continue;

            /* Found another term. */
            ++found;
            if (found == n) return v;
        }
    }
}
